DROP TABLE IF EXISTS `customer_entity`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `customer_entity` (
  `customer_id` varchar(100) NOT NULL,
  `customer_code` varchar(100) DEFAULT NULL,
  `customer_name` varchar(100) DEFAULT NULL,
  `customer_level` varchar(100) DEFAULT NULL,
  `primary_industry` varchar(100) DEFAULT NULL,
  `secondary_industry` varchar(100) DEFAULT NULL,
  `company_size` varchar(100) DEFAULT NULL,
  `established_year` varchar(100) DEFAULT NULL,
  `annual_revenue` varchar(100) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `province` varchar(100) DEFAULT NULL,
  `contact_person` varchar(100) DEFAULT NULL,
  `contact_phone` varchar(100) DEFAULT NULL,
  `contact_email` varchar(100) DEFAULT NULL,
  `is_named_customer` varchar(100) DEFAULT NULL,
  `has_contract` varchar(100) DEFAULT NULL,
  `created_date` varchar(100) DEFAULT NULL,
  `status` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`customer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

