DROP TABLE IF EXISTS `material_procurement_event`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `material_procurement_event` (
  `procurement_id` varchar(100) NOT NULL,
  `procurement_number` varchar(100) DEFAULT NULL,
  `procurement_date` varchar(100) DEFAULT NULL,
  `supplier_id` varchar(100) DEFAULT NULL,
  `supplier_code` varchar(100) DEFAULT NULL,
  `supplier_name` varchar(100) DEFAULT NULL,
  `material_id` varchar(100) DEFAULT NULL,
  `material_code` varchar(100) DEFAULT NULL,
  `material_name` varchar(100) DEFAULT NULL,
  `warehouse_id` varchar(100) DEFAULT NULL,
  `warehouse_name` varchar(100) DEFAULT NULL,
  `quantity` int DEFAULT NULL,
  `unit_price` double DEFAULT NULL,
  `total_amount` double DEFAULT NULL,
  `currency` varchar(100) DEFAULT NULL,
  `tax_rate` double DEFAULT NULL,
  `payment_terms` varchar(100) DEFAULT NULL,
  `logistics_provider` varchar(100) DEFAULT NULL,
  `tracking_number` varchar(100) DEFAULT NULL,
  `ship_date` varchar(100) DEFAULT NULL,
  `estimated_delivery_date` varchar(100) DEFAULT NULL,
  `actual_delivery_date` varchar(100) DEFAULT NULL,
  `inspection_status` varchar(100) DEFAULT NULL,
  `notes` varchar(100) DEFAULT NULL,
  `created_date` varchar(100) DEFAULT NULL,
  `status` varchar(100) DEFAULT NULL,
  `po_number` varchar(100) DEFAULT NULL,
  `delivery_batch` varchar(100) DEFAULT NULL,
  `total_batches` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`procurement_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

