DROP TABLE IF EXISTS `material_requisition_event`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `material_requisition_event` (
  `material_requisition_id` varchar(100) NOT NULL,
  `requisition_number` varchar(100) DEFAULT NULL,
  `requisition_type` varchar(100) DEFAULT NULL,
  `material_id` varchar(100) DEFAULT NULL,
  `material_code` varchar(100) DEFAULT NULL,
  `material_name` varchar(100) DEFAULT NULL,
  `warehouse_id` varchar(100) DEFAULT NULL,
  `factory_id` varchar(100) DEFAULT NULL,
  `requested_quantity` double DEFAULT NULL,
  `issued_quantity` double DEFAULT NULL,
  `unit` varchar(100) DEFAULT NULL,
  `requisition_date` varchar(100) DEFAULT NULL,
  `issue_date` varchar(100) DEFAULT NULL,
  `production_order_number` varchar(100) DEFAULT NULL,
  `purpose` varchar(100) DEFAULT NULL,
  `status` varchar(100) DEFAULT NULL,
  `created_date` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`material_requisition_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
