DROP TABLE IF EXISTS `purchase_order_event_update`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `purchase_order_event_update` (
  `purchase_order_id` varchar(100) NOT NULL,
  `purchase_order_number` varchar(100) DEFAULT NULL,
  `document_date` varchar(100) DEFAULT NULL,
  `supplier_id` varchar(100) DEFAULT NULL,
  `supplier_name` varchar(100) DEFAULT NULL,
  `material_id` varchar(100) DEFAULT NULL,
  `material_code` varchar(100) DEFAULT NULL,
  `material_name` varchar(100) DEFAULT NULL,
  `purchase_quantity` double DEFAULT NULL,
  `unit_price_tax` double DEFAULT NULL,
  `tax_rate` double DEFAULT NULL,
  `document_status` varchar(100) DEFAULT NULL,
  `required_date` varchar(100) DEFAULT NULL,
  `planned_arrival_date` varchar(100) DEFAULT NULL,
  `accumulated_arrival_tax` double DEFAULT NULL,
  `accumulated_storage_tax` double DEFAULT NULL,
  `payment_terms` varchar(100) DEFAULT NULL,
  `buyer` varchar(100) DEFAULT NULL,
  `created_date` varchar(100) DEFAULT NULL,
  `status` varchar(100) DEFAULT NULL,
  `srcbillid` varchar(100) DEFAULT NULL,
  `srcbillentryid` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`purchase_order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

