DROP TABLE IF EXISTS `sales_order_event`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_order_event` (
  `sales_order_id` varchar(100) NOT NULL,
  `sales_order_number` varchar(100) DEFAULT NULL,
  `document_date` varchar(100) DEFAULT NULL,
  `customer_id` varchar(100) DEFAULT NULL,
  `customer_name` varchar(100) DEFAULT NULL,
  `line_number` int DEFAULT NULL,
  `product_id` varchar(100) DEFAULT NULL,
  `product_code` varchar(100) DEFAULT NULL,
  `product_name` varchar(100) DEFAULT NULL,
  `quantity` int DEFAULT NULL,
  `unit` varchar(100) DEFAULT NULL,
  `standard_price` int DEFAULT NULL,
  `discount_rate` varchar(100) DEFAULT NULL,
  `actual_price` decimal(10,0) DEFAULT NULL,
  `subtotal_amount` decimal(10,0) DEFAULT NULL,
  `order_status` varchar(100) DEFAULT NULL,
  `document_status` varchar(100) DEFAULT NULL,
  `transaction_type` varchar(100) DEFAULT NULL,
  `sales_department` varchar(100) DEFAULT NULL,
  `salesperson` varchar(100) DEFAULT NULL,
  `planned_delivery_date` varchar(100) DEFAULT NULL,
  `is_urgent` varchar(100) DEFAULT NULL,
  `contract_number` varchar(100) DEFAULT NULL,
  `project_name` varchar(100) DEFAULT NULL,
  `end_customer` varchar(100) DEFAULT NULL,
  `quotation_number` varchar(100) DEFAULT NULL,
  `notes` varchar(100) DEFAULT NULL,
  `created_date` varchar(100) DEFAULT NULL,
  `status` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`sales_order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

