DROP TABLE IF EXISTS `shipment_event`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `shipment_event` (
  `shipment_id` varchar(100) NOT NULL,
  `shipment_number` varchar(100) DEFAULT NULL,
  `shipment_date` varchar(100) DEFAULT NULL,
  `warehouse_id` varchar(100) DEFAULT NULL,
  `warehouse_name` varchar(100) DEFAULT NULL,
  `quantity` double DEFAULT NULL,
  `consignee` varchar(100) DEFAULT NULL,
  `consignee_phone` varchar(100) DEFAULT NULL,
  `delivery_address` varchar(100) DEFAULT NULL,
  `logistics_provider` varchar(100) DEFAULT NULL,
  `tracking_number` varchar(100) DEFAULT NULL,
  `actual_delivery_date` varchar(100) DEFAULT NULL,
  `delivery_status` varchar(100) DEFAULT NULL,
  `sales_order_number` varchar(100) DEFAULT NULL,
  `notes` varchar(100) DEFAULT NULL,
  `created_date` varchar(100) DEFAULT NULL,
  `status` varchar(100) DEFAULT NULL,
  `customer_id` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`shipment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
