--
-- Table structure for table `supplier_entity`
--

DROP TABLE IF EXISTS `supplier_entity`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `supplier_entity` (
  `supplier_id` varchar(100) NOT NULL,
  `supplier_code` varchar(100) DEFAULT NULL,
  `supplier_name` varchar(100) DEFAULT NULL,
  `supplier_short_name` varchar(100) DEFAULT NULL,
  `supplier_category` varchar(100) DEFAULT NULL,
  `supplier_tier` varchar(100) DEFAULT NULL,
  `primary_contact` varchar(100) DEFAULT NULL,
  `contact_phone` varchar(100) DEFAULT NULL,
  `contact_email` varchar(100) DEFAULT NULL,
  `registered_address` varchar(100) DEFAULT NULL,
  `country` varchar(100) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `settlement_currency` varchar(100) DEFAULT NULL,
  `default_tax_rate` double DEFAULT NULL,
  `payment_terms` varchar(100) DEFAULT NULL,
  `lead_time_avg` int DEFAULT NULL,
  `risk_level` varchar(100) DEFAULT NULL,
  `is_active` varchar(100) DEFAULT NULL,
  `established_year` int DEFAULT NULL,
  `annual_capacity` varchar(100) DEFAULT NULL,
  `created_date` varchar(100) DEFAULT NULL,
  `status` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`supplier_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

